<template><div class="coauthors"><AppChip v-for="person in modelValue" :key="person.email" removable :title="person.email" :remove-label="'Убрать '+person.name" @remove="remove(person.email)">{{ person.name }}</AppChip><MemberPicker :members="available" label="+ Соавтор" placeholder="Имя <email> или поиск" allow-custom @pick="pick" @create="create" /></div></template><script setup lang="ts">import{computed}from'vue';import AppChip from '@shared/ui/AppChip.vue';import MemberPicker from '@shared/ui/MemberPicker.vue';import type{Coauthor}from'../git-types';const props=defineProps<{modelValue:Coauthor[];known:Coauthor[]}>();const emit=defineEmits<{'update:modelValue':[value:Coauthor[]]}>();const available=computed(()=>props.known.filter(p=>!props.modelValue.some(m=>m.email===p.email)).map(p=>({value:p.email,login:p.email,name:p.name})));function add(person:Coauthor){if(!props.modelValue.some(p=>p.email.toLowerCase()===person.email.toLowerCase()))emit('update:modelValue',[...props.modelValue,person])}function pick(email:string){const person=props.known.find(p=>p.email===email);if(person)add(person)}function create(value:string){const match=value.match(/^(.+?)\s*<([^<>\s]+@[^<>\s]+)>$/);if(match)add({name:match[1].trim(),email:match[2]})}function remove(email:string){emit('update:modelValue',props.modelValue.filter(p=>p.email!==email))}</script><style scoped>.coauthors{display:flex;flex-wrap:wrap;gap:var(--sp-1);align-items:center}</style>
